package cn.xi.cloudwidget;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.BitmapDrawable;
import android.os.*;
import android.util.SizeF;
import android.view.*;
import android.widget.*;
import org.xmlpull.v1.*;
import java.io.*;
import java.util.*;

/** Regressions for actual-host mismatch and white border contrast. */
public class StretchChecks extends ReviewFixChecks {
    @Override public void onStart(){String phase=args.getString("phase","");if(phase.equals("previous")){super.onStart();return;}Bundle output=new Bundle();try{c=getTargetContext();
        if(phase.equals("upgrade")){XmlPullParser parser=android.util.Xml.newPullParser();try(InputStream input=getContext().getAssets().open("v031-snapshot.xml")){parser.setInput(input,"UTF-8");int event;while((event=parser.next())!=XmlPullParser.END_DOCUMENT)if(event==XmlPullParser.START_TAG&&parser.getName().equals("string")){String name=parser.getAttributeValue(null,"name"),value=parser.nextText();check(value.equals(c.getSharedPreferences("cards-v1",0).getString(name,null)),"v031 preference unchanged "+name);}}}
        else {mismatch();contrast();}
        output.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,output);
    }catch(Throwable e){output.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,output);}}
    void png32(Bitmap image,String name)throws Exception{File dir=new File(c.getFilesDir(),"review032");dir.mkdirs();try(OutputStream stream=new FileOutputStream(new File(dir,name))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}}
    ImageView ready(AppWidgetHostView view)throws Throwable{ImageView[] image={null};long deadline=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<deadline){main(()->image[0]=view.findViewById(R.id.card));if(image[0]!=null&&image[0].getWidth()>0&&image[0].getDrawable()!=null)return image[0];SystemClock.sleep(100);}throw new AssertionError("native ImageView not ready");}
    float[] imageMatrix(ImageView view)throws Throwable{float[] values=new float[9];main(()->view.getImageMatrix().getValues(values));return values;}
    void mismatch()throws Throwable{
        StretchHostActivity host=(StretchHostActivity)startActivitySync(new Intent(c,StretchHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
        for(int n=0;n<2;n++){
            int shape=n,id=host.ids.get(n);AppWidgetHostView view=host.actual.get(n);ImageView image=ready(view);SizeF report=host.reported.get(n);float actualWidth=view.getWidth()/c.getResources().getDisplayMetrics().density,actualHeight=view.getHeight()/c.getResources().getDisplayMetrics().density;
            check(Math.abs(report.getWidth()/report.getHeight()-actualWidth/actualHeight)>.15f,"host deliberately differs from reported aspect "+shape);float[] before=imageMatrix(image);check(Math.abs(before[Matrix.MSCALE_X]-before[Matrix.MSCALE_Y])<.001,"native bitmap is uniformly scaled before measurement "+shape);
            final ImageView beforeView=image;main(()->{Bitmap bitmap=((BitmapDrawable)beforeView.getDrawable()).getBitmap();float[] values=new float[9];beforeView.getImageMatrix().getValues(values);check(values[Matrix.MTRANS_X]>=-.5&&values[Matrix.MTRANS_Y]>=-.5&&bitmap.getWidth()*values[Matrix.MSCALE_X]<=beforeView.getWidth()+1&&bitmap.getHeight()*values[Matrix.MSCALE_Y]<=beforeView.getHeight()+1,"entire bitmap remains visible without cropping "+shape);});
            ActivityMonitor monitor=addMonitor(EditorActivity.class.getName(),null,false);main(()->view.findViewById(R.id.hits).performClick());Activity result=monitor.waitForActivityWithTimeout(8000);removeMonitor(monitor);check(result instanceof EditorActivity,"real root click opens editor "+shape);EditorActivity editor=(EditorActivity)result;waitForIdleSync();Rect bounds=editor.getIntent().getSourceBounds();check(bounds!=null&&bounds.width()==view.getWidth()&&bounds.height()==view.getHeight(),"framework delivers actual whole-widget bounds "+shape);
            SizeF measured=WidgetGeometry.measured(c,id,report);long geometryReady=SystemClock.uptimeMillis()+3000;while(measured==null&&SystemClock.uptimeMillis()<geometryReady){SystemClock.sleep(50);waitForIdleSync();measured=WidgetGeometry.measured(c,id,report);}this.report.append("GEOMETRY expectedId=").append(id).append(" actualId=").append(editor.getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1)).append(" flag=").append(editor.getIntent().getBooleanExtra("measureWidget",false)).append(" density=").append(editor.getIntent().getFloatExtra("geometryDensity",0)).append(" appDensity=").append(c.getResources().getDisplayMetrics().density).append(" requested=").append(WidgetGeometry.requested(editor.getIntent())).append(" oldStamp=").append(editor.getIntent().getStringExtra("geometryStamp")).append(" currentStamp=").append(WidgetGeometry.stamp(c,id)).append(" measured=").append(measured).append(" expected=").append(actualWidth).append("x").append(actualHeight).append("\n");check(measured!=null&&Math.abs(measured.getWidth()-actualWidth)<.1&&Math.abs(measured.getHeight()-actualHeight)<.1,"actual native bounds retained per widget "+shape);CardPreview preview=(CardPreview)field("preview").get(editor);check(Math.abs(preview.targetWidth/preview.targetHeight-actualWidth/actualHeight)<.001,"editor uses measured aspect instead of launcher report "+shape);
            main(editor::finish);waitForIdleSync();long deadline=SystemClock.uptimeMillis()+8000;ImageView after=null;while(SystemClock.uptimeMillis()<deadline){after=ready(view);Bitmap bitmap=((BitmapDrawable)after.getDrawable()).getBitmap();if(Math.abs((float)bitmap.getWidth()/bitmap.getHeight()-actualWidth/actualHeight)<.01)break;SystemClock.sleep(100);}check(after!=null&&Math.abs((float)((BitmapDrawable)after.getDrawable()).getBitmap().getWidth()/((BitmapDrawable)after.getDrawable()).getBitmap().getHeight()-actualWidth/actualHeight)<.01,"widget re-renders for actual measured aspect "+shape);float[] matrix=imageMatrix(after);check(Math.abs(matrix[Matrix.MSCALE_X]-matrix[Matrix.MSCALE_Y])<.001,"native bitmap remains uniformly scaled after calibration "+shape);
            SystemClock.sleep(100);waitForIdleSync();CardLayout physical=new CardLayout(new Store(c).get(new Store(c).binding(id)),view.getWidth(),view.getHeight());main(()->{TextClock clock=view.findViewById(R.id.clock),date=view.findViewById(R.id.date);int[] origin=new int[2],timePosition=new int[2],datePosition=new int[2];view.getLocationOnScreen(origin);clock.getLocationOnScreen(timePosition);date.getLocationOnScreen(datePosition);check(Math.abs(timePosition[0]-origin[0]-(physical.left+physical.pad*physical.scale))<=2&&Math.abs(timePosition[1]-origin[1]-(physical.top+physical.clockTop()*physical.scale))<=2,"native clock position follows measured geometry "+shape);check(Math.abs(datePosition[1]-origin[1]-(physical.top+(physical.clockTop()+physical.clockLine())*physical.scale))<=2,"native date position follows measured geometry "+shape);check(Math.abs(clock.getTextSize()-physical.clockSize()*physical.scale)<.5,"native clock size follows measured geometry "+shape);});
            Card card=new Store(c).get(new Store(c).binding(id));Bitmap expected=Renderer.render(c,card,view.getWidth(),view.getHeight(),true);final Bitmap[] nativeImage={null};main(()->{nativeImage[0]=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(nativeImage[0]));});png32(expected,"measured-preview-"+shape+".png");png32(nativeImage[0],"measured-widget-"+shape+".png");expected.recycle();nativeImage[0].recycle();
            Bundle options=AppWidgetManager.getInstance(c).getAppWidgetOptions(id);Bundle changed=new Bundle(options);changed.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT)+1);AppWidgetManager.getInstance(c).updateAppWidgetOptions(id,changed);check(WidgetGeometry.measured(c,id,report)==null,"changed launcher size invalidates measured cache "+shape);AppWidgetManager.getInstance(c).updateAppWidgetOptions(id,options);
        }
        checklist(host);
    }
    void checklist(StretchHostActivity host)throws Throwable{
        int id=host.ids.get(0);AppWidgetHostView view=host.actual.get(0);Store store=new Store(c);Card original=store.get(store.binding(id)),checkCard=Card.from(original.json().toString());checkCard.type=4;store.save(checkCard);WidgetProvider.update(c,id);long ready=SystemClock.uptimeMillis()+5000;LinearLayout[] hits={null};while(SystemClock.uptimeMillis()<ready){main(()->hits[0]=view.findViewById(R.id.hits));if(hits[0]!=null&&hits[0].getChildCount()==5)break;SystemClock.sleep(50);}check(hits[0]!=null&&hits[0].getChildCount()==5,"legacy-height checklist builds header, three rows and footer");SystemClock.sleep(100);
        CardLayout layout=new CardLayout(checkCard,view.getWidth(),view.getHeight());float x=layout.left+40*layout.scale,y=layout.top+63*layout.scale;main(()->touch(hits[0],x,y));long deadline=SystemClock.uptimeMillis()+5000;while(!store.get(checkCard.id).done(0,java.time.LocalDate.now())&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(50);check(store.get(checkCard.id).done(0,java.time.LocalDate.now()),"native touch lands on first checklist row with Android-10-compatible heights");check(!store.get(store.binding(host.ids.get(1))).done(0,java.time.LocalDate.now()),"checklist touch leaves other instance independent");
        ActivityMonitor monitor=addMonitor(EditorActivity.class.getName(),null,false);main(()->touch(hits[0],x,layout.top+20*layout.scale));Activity result=monitor.waitForActivityWithTimeout(8000);removeMonitor(monitor);check(result instanceof EditorActivity,"checklist header touch bubbles to whole-widget editor");Rect bounds=result.getIntent().getSourceBounds();check(bounds!=null&&bounds.width()==view.getWidth()&&bounds.height()==view.getHeight(),"checklist editing measures the whole widget, not a header row");check(store.get(checkCard.id).done(0,java.time.LocalDate.now()),"opening measured editor preserves checklist completion");main(result::finish);store.save(original);WidgetProvider.update(c,id);
    }
    static void touch(View view,float x,float y){long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(now,now+50,MotionEvent.ACTION_UP,x,y,0);view.dispatchTouchEvent(down);view.dispatchTouchEvent(up);down.recycle();up.recycle();}
    void contrast()throws Throwable{
        Card card=new Card();card.borderInk=-1;int background=card.background;double white=Controls.luminance(-1),blue=Controls.luminance(Controls.borderBackdrop(-1));check((white+.05)/(blue+.05)>=4.5,"white border thumbnail backdrop provides strong contrast");check(Controls.borderBackdrop(-1)!=Controls.borderBackdrop(0xff111111),"light and dark borders choose different preview backdrops");
        for(int style=1;style<Borders.NAMES.length;style++){final int index=style;main(()->{Controls.BorderThumb thumb=new Controls.BorderThumb(c,card,index);int side=Ui.dp(c,90);thumb.measure(View.MeasureSpec.makeMeasureSpec(side,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(side,View.MeasureSpec.EXACTLY));thumb.layout(0,0,side,side);Bitmap image=Bitmap.createBitmap(side,side,Bitmap.Config.ARGB_8888);thumb.draw(new Canvas(image));int whitePixels=0,bluePixels=0;for(int y=0;y<side;y++)for(int x=0;x<side;x++){int pixel=image.getPixel(x,y);if(Color.alpha(pixel)>240&&Color.red(pixel)>240&&Color.green(pixel)>240&&Color.blue(pixel)>240)whitePixels++;if(pixel==Controls.borderBackdrop(-1))bluePixels++;}check(whitePixels>8&&bluePixels>100,"white border visible against contrasting thumbnail style "+index);png32(image,"white-border-"+index+".png");image.recycle();});}check(card.background==background&&card.borderInk==-1,"thumbnail backdrop never changes saved card colors");
        card.id="qa034-white-border";card.border=2;card.background=0xffdceaf2;card.body="白色边框预览";card.type=3;new Store(c).save(card);
    }
}
